files = list(set(files))
print(f'Scanning {len(files)} PDFs...')
pat1 = re.compile(rb\"party.{0,3}s\s+over\", re.I)
pat2 = re.compile(rb'se.orita', re.I)
hits = []
for f in files:
    try:
        with open(f, 'rb') as fh:
            raw = fh.read()
    except Exception:
        continue
    found = False
    for m in re.finditer(rb'stream\r?\n(.*?)endstream', raw, re.S):
        chunk = m.group(1)
        try:
            dec = zlib.decompress(chunk)
        except Exception:
            dec = None
        for c in ([chunk, dec] if dec else [chunk]):
